import{_ as s}from"./chunks/mmad_unitflag.CrF-fUH6.js";import{_ as p,o as n,a as l,b as e}from"./app.DKoEZOcr.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"矩阵计算","link":"/api/SIMD-API/tensor_api/matrix_compute/matrix_compute"},{"text":"mmad计算关键特性说明","link":"/api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/mmad_compute_key_features"},{"text":"unit_flag","link":"/api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/unit_flag"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/unit_flag.md","filePath":"api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/unit_flag.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"相关接口","slug":"相关接口","link":"#相关接口"},{"level":2,"title":"沿K轴迭代循环使用示例片段","slug":"沿K轴迭代循环使用示例片段","link":"#沿K轴迭代循环使用示例片段"}],"lastUpdated":1787967772000}'),c={name:"api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/unit_flag.md"};function t(i,a,d,_,m,o){return n(),l("div",null,[...a[0]||(a[0]=[e('<div><article class="markdown-body"><h1>unit_flag</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>unit_flag的核心功能体现为：mmad和copy接口引入了单元标志（unit-flag）机制，通过以内存块为粒度实现精细化的数据同步，从而有效降低同步延迟，提升系统整体性能。当unit_flag开关打开后，对于L0C Buffer中的每个内存块（512B），提供一个单元标志位，用于指示该块是否可读或可写。</p><p>mmad和copy接口将unit_flag设置为<code>unit_flag_mode::enable_keep</code>或<code>unit_flag_mode::enable_update</code>后，系统会启动单元标志位。</p><p>当<code>params.unit_flag</code>为<code>unit_flag_mode::enable_keep</code>（底层值为2）时，使能unit_flag功能，在硬件执行完指令后，不改变单元标志位。</p><ul><li>对于写操作（mmad接口），如果单元标志位0，则硬件直接写入L0C Buffer，否则，如果单元标志位为1，则写操作会等待直到单元标志变为0，执行完成后将单元标志位保持为0。</li><li>对于读操作（copy接口），如果单元标志位1，则硬件直接读取L0C Buffer，否则，如果单元标志位为0，则读操作为等待直到单元标志变为1，执行完成后将单元标志位保持为1。</li></ul><p>当<code>params.unit_flag</code>为<code>unit_flag_mode::enable_update</code>（底层值为3）时，使能unit_flag功能，在硬件执行完指令后，改变单元标志位。</p><ul><li>对于写操作（mmad接口），如果单元标志位0，则硬件直接写入L0C Buffer，否则，如果单元标志位为1，则写操作会等待直到单元标志变为0，执行完成后将单元标志位设置成1。</li><li>对于读操作（copy接口），如果单元标志位1，则硬件直接读取L0C Buffer，否则，如果单元标志位为0，则读操作为等待直到单元标志变为1，执行完成后将单元标志位设置成0。</li></ul><p>根据上述特性，如果用户在进行A矩阵维度为128×1024、B矩阵维度为1024×128的矩阵乘计算时，需要沿着K轴进行迭代循环，假设每次迭代K长度为128，则需要迭代8次，此时8次mmad指令对应1次Fixpipe指令。</p><ul><li>前7次mmad的unit_flag都设置为<code>unit_flag_mode::enable_keep</code>，写入后将单元标志位始终为0，保证后续mmad可以写入L0C Buffer。</li><li>最后1次mmad设置为<code>unit_flag_mode::enable_update</code>，写入后将单元标志位设置成1，保证Fixpipe可以读取L0C Buffer。</li><li>Fixpipe的unit_flag设置为<code>unit_flag_mode::enable_update</code>，读取后将单元标志位设置为0，保证后续mmad接口可以顺利写入L0C Buffer数据。</li></ul><p>如果用户需要单次mmad的结果分多次搬出时，譬如mmad计算结果的L0C Buffer为M(128) × N(256)，沿N轴分两次搬出，这样一次mmad会对应两次Fixpipe。</p><ul><li>mmad的时候需要将unit_flag设置为<code>unit_flag_mode::enable_update</code>，保证Fixpipe可以读取L0C Buffer数据。</li><li>每一次Fixpipe的unit_flag都设置为<code>unit_flag_mode::enable_update</code>，读取后将单元标志位设置为0，保证后续其他mmad接口在复用这块L0C Buffer地址时可以顺利写入数据。</li></ul><p>当开启unit_flag后，mmad和Fixpipe会对同一块分形的L0C Buffer进行读写操作，因此mmad计算和Fixpipe保持一致的读写顺序，有助于获得更优的性能表现。</p><p>在调用mmad接口时，需要通过<a href="../../../c_api/cube_compute/asc_set_mmad_direction_m.html">asc_set_mmad_direction_m</a>或<a href="../../../c_api/cube_compute/asc_set_mmad_direction_n.html">asc_set_mmad_direction_n</a>接口设置mmad的计算方向。当Fixpipe使能了NZ2ND或ChannelMerge等layout变换时，需将mmad的计算方向设置为N方向优先，即调用<code>asc_set_mmad_direction_n</code>。反之，若未使用这些特性，则应将计算方向设置为M方向优先，即调用<code>asc_set_mmad_direction_m</code>。</p><p><strong>图1</strong> mmad和Fixpipe同时沿M方向写/读</p><p><img src="'+s+`" alt="mmad-Fixpipe读写示意图"></p><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><ul><li>mmad和copy接口均提供了unit_flag参数来控制该功能的启用，需确保两者同步开启，才能正常生效。</li><li>当希望控制同一块L0C Buffer内存空间能持续只被多条mmad或多条Fixpipe指令操作时，需将对应的前n-1条指令的unit_flag值设置为<code>unit_flag_mode::enable_keep</code>，维持被操作内存空间的持续占用状态，最后一条指令设置为<code>unit_flag_mode::enable_update</code>，解除被占用状态。</li><li>当启用unit_flag功能后，建议mmad的计算数据量与Fixpipe搬出的数据量保持一致。若mmad计算了大块数据（M × N = 128 × 128），但Fixpipe只搬出了其中一部分数据（M × N = 64 × 64），则可能会导致执行异常，可以通过<code>SetFixPipeConfig</code>接口重置L0C Buffer的状态。</li></ul><h2 id="相关接口">相关接口<a class="header-anchor" href="#相关接口">​</a></h2><ul><li><a href="../mmad_compute/mmad.html">mmad</a></li><li><a href="../cube_compute_store/copy_l0c_to_gm.html">copy（L0C到GM数据搬运）</a></li><li><a href="../cube_compute_store/copy_l0c_to_ub.html">copy（L0C到UB数据搬运）</a></li><li><a href="../../../c_api/cube_compute/asc_set_mmad_direction_m.html">asc_set_mmad_direction_m</a></li><li><a href="../../../c_api/cube_compute/asc_set_mmad_direction_n.html">asc_set_mmad_direction_n</a></li></ul><h2 id="沿K轴迭代循环使用示例片段">沿K轴迭代循环使用示例片段<a class="header-anchor" href="#沿K轴迭代循环使用示例片段">​</a></h2><p>以下示例仅展示<code>unit_flag</code>在K轴迭代循环中的设置方式，省略张量构造和参数初始化。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>

<span class="c1">// 调用k_round次mmad。</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="k">auto</span><span class="w"> </span><span class="n">k_index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">k_index</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">k_round</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">k_index</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">k_index</span><span class="w"> </span><span class="o">!=</span><span class="w"> </span><span class="n">k_round</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 前k_round-1次迭代保持单元标志位，保证mmad在K迭代循环中可以一直写入L0C Buffer。</span>
<span class="w">        </span><span class="n">params</span><span class="p">.</span><span class="n">unit_flag</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">unit_flag_mode</span><span class="o">::</span><span class="n">enable_keep</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 最后一次迭代更新单元标志位，保证Fixpipe可以读L0C Buffer。</span>
<span class="w">        </span><span class="n">params</span><span class="p">.</span><span class="n">unit_flag</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">unit_flag_mode</span><span class="o">::</span><span class="n">enable_update</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">mmad_atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_mmad</span><span class="p">(</span><span class="n">mmad_operation</span><span class="p">{}).</span><span class="n">with</span><span class="p">(</span><span class="n">params</span><span class="p">);</span>
<span class="w">    </span><span class="n">mmad</span><span class="p">(</span><span class="n">mmad_atom</span><span class="p">,</span><span class="w"> </span><span class="n">l0c</span><span class="p">,</span><span class="w"> </span><span class="n">l0a</span><span class="p">,</span><span class="w"> </span><span class="n">l0b</span><span class="p">);</span>
<span class="p">}</span>
<span class="c1">// Fixpipe一次搬出。</span>
<span class="c1">// Fixpipe更新单元标志位，保证后续mmad接口可以顺利写入L0C Buffer数据。</span>
<span class="n">l0c_to_gm_params</span><span class="w"> </span><span class="n">fixpipe_params</span><span class="p">;</span>
<span class="n">fixpipe_params</span><span class="p">.</span><span class="n">unit_flag</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">unit_flag_mode</span><span class="o">::</span><span class="n">enable_update</span><span class="p">;</span>
<span class="k">auto</span><span class="w"> </span><span class="n">fixpipe_atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_l0c_to_gm</span><span class="p">{}).</span><span class="n">with</span><span class="p">(</span><span class="n">fixpipe_params</span><span class="p">);</span>
<span class="n">copy</span><span class="p">(</span><span class="n">fixpipe_atom</span><span class="p">,</span><span class="w"> </span><span class="n">gm</span><span class="p">,</span><span class="w"> </span><span class="n">l0c</span><span class="p">);</span>
</code></pre></div><p><strong>表1</strong> 性能示例说明（以输入数据类型half为例，无业务实测表示忽略指令的前后序操作，只考虑单指令性能，包含带宽延迟等开销）</p><table><thead><tr><th>M</th><th>N</th><th>K</th><th>unit_flag</th><th>LOOP_COUNT</th><th>mmad理论值（cycle）</th><th>mmad无业务实测值（cycle）</th></tr></thead><tbody><tr><td>128</td><td>256</td><td>512</td><td>Enable</td><td>8</td><td>4156</td><td>4209</td></tr><tr><td>128</td><td>256</td><td>512</td><td>Disable</td><td>8</td><td>4156</td><td>4225</td></tr><tr><td>128</td><td>128</td><td>512</td><td>Enable</td><td>8</td><td>2108</td><td>2172</td></tr><tr><td>128</td><td>128</td><td>512</td><td>Disable</td><td>8</td><td>2108</td><td>2172</td></tr></tbody></table></article></div>`,1)])])}const h=p(c,[["render",t]]);export{f as __pageData,h as default};
